CREATE OR REPLACE FUNCTION public.validate_website_value() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF length(NEW.key)>120 OR length(NEW.value)>6000 THEN RAISE EXCEPTION 'Content is too long'; END IF; IF NEW.key IN ('contact.phone','contact.snack_phone') AND NEW.value !~ '^\+?[0-9 ()-]{10,25}$' THEN RAISE EXCEPTION 'Enter a valid phone number'; END IF; IF NEW.key LIKE '%.photo' OR NEW.key IN ('home.hero','home.how','home.league') THEN IF NEW.value <> '' AND NEW.value !~ '^https://' AND NEW.value !~ '^/__l5e/assets-v1/[0-9a-f-]+/[A-Za-z0-9._-]+$' THEN RAISE EXCEPTION 'Use a secure image link'; END IF; END IF; RETURN NEW; END $$;